package com.getcapacitor; public class JSObject extends java.util.HashMap<String,Object> { public JSObject put(String k,Object v){ super.put(k,v); return this; } public JSObject put(String k,int v){ super.put(k,v); return this; } public JSObject put(String k,long v){ super.put(k,v); return this; } public JSObject put(String k,boolean v){ super.put(k,v); return this; } public boolean has(String k){ return containsKey(k);} }
